ation data by combining the latest and aggregated values with an optional simplified chart.', '{weather,environment,vibration,tremor,shake,quiver,jolt,oscillation,pulsation,resonance}', NULL, 1, 'timeseries', '[{"id" : "eea3a2c0-6570-11f1-9578-071530b96ddb", "name" : "Outdoor Environment"}]');
INSERT INTO "widget_type_info_view" ("id", "created_time", "fqn", "descriptor", "name", "tenant_id", "image", "scada", "deprecated", "description", "tags", "external_id", "version", "widget_type", "bundles") VALUES ('e2532b80-6570-11f1-9578-071530b96ddb', 1781167093304, 'horizontal_rotational_speed_card', '{"type":"latest","sizeX":5,"sizeY":1,"resources":[],"templateHtml":"<tb-value-card-widget \n    [ctx]=\"ctx\"\n    [widgetTitlePanel]=\"widgetTitlePanel\">\n</tb-value-card-widget>","templateCss":"#container {\n    overflow: auto;\n}\n\n.tbDatasource-container {\n    margin: 5px;\n    padding: 8px;\n}\n\n.tbDatasource-title {\n    font-size: 1.200rem;\n    font-weight: 500;\n    padding-bottom: 10px;\n}\n\n.tbDatasource-table {\n    width: 100%;\n    box-shadow: 0 0 10px #ccc;\n    border-collapse: collapse;\n    white-space: nowrap;\n    font-size: 1.000rem;\n    color: #757575;\n}\n\n.tbDatasource-table td {\n    position: relative;\n    border-top: 1px solid rgba(0, 0, 0, 0.12);\n    border-bottom: 1px solid rgba(0, 0, 0, 0.12);\n    padding: 0px 18px;\n    box-sizing: border-box;\n}","controllerScript":"self.onInit = function() {\n    self.ctx.$scope.valueCardWidget.onInit();\n};\n\nself.onDataUpdated = function() {\n    self.ctx.$scope.valueCardWidget.onDataUpdated();\n};\n\nself.typeParameters = function() {\n    return {\n        maxDatasources: 1,\n        maxDataKeys: 1,\n        singleEntity: true,\n        horizontal: true,\n        previewWidth: ''420px'',\n        previewHeight: ''90px'',\n        embedTitlePanel: true,\n        supportsUnitConversion: true,\n        defaultDataKeysFunction: function() {\n            return [{ name: ''rotationalSpeed'', label: ''Rotational speed'', type: ''timeseries'' }];\n        }\n    };\n};\n\nself.onDestroy = function() {\n};\n","dataKeySettingsSchema":"{}\n","settingsDirective":"tb-value-card-widget-settings","hasBasicMode":true,"basicModeDirective":"tb-value-card-basic-config","defaultConfig":"{\"datasources\"