 1, 'timeseries', '[{"id" : "ed2d7d80-6570-11f1-9578-071530b96ddb", "name" : "Air quality"},{"id" : "ee6e3ae0-6570-11f1-9578-071530b96ddb", "name" : "Indoor Environment"}]');
INSERT INTO "widget_type_info_view" ("id", "created_time", "fqn", "descriptor", "name", "tenant_id", "image", "scada", "deprecated", "description", "tags", "external_id", "version", "widget_type", "bundles") VALUES ('e33fd570-6570-11f1-9578-071530b96ddb', 1781167094855, 'control_widgets.rpc_debug_terminal', '{"type":"rpc","sizeX":9.5,"sizeY":5.5,"resources":[],"templateHtml":"<div style=\"height: 100%; overflow-y: auto;\" id=\"device-terminal\"></div>","templateCss":".cmd .cursor.blink {\n    -webkit-animation-name: terminal-underline;\n       -moz-animation-name: terminal-underline;\n        -ms-animation-name: terminal-underline;\n            animation-name: terminal-underline;\n}\n.terminal .inverted, .cmd .inverted {\n    border-bottom-color: #aaa;\n}\n\n","controllerScript":"var requestTimeout = 500;\nvar requestPersistent = false;\nvar persistentPollingInterval = 5000;\n\nself.onInit = function() {\n    var subscription = self.ctx.defaultSubscription;\n    var rpcEnabled = subscription.rpcEnabled;\n    var deviceName = ''Simulated'';\n    var prompt;\n    if (subscription.targetEntityName && subscription.targetEntityName.length) {\n        deviceName = subscription.targetEntityName;\n    }\n    if (self.ctx.settings.requestTimeout) {\n        requestTimeout = self.ctx.settings.requestTimeout;\n    }\n    if (self.ctx.settings.requestPersistent) {\n        requestPersistent = self.ctx.settings.requestPersistent;\n    }\n    if (self.ctx.settings.persistentPollingInterval) {\n        persistentPollingInterval = self.ctx.settings.persistentPollingInterval;\n    }\n    var greetings = ''Welcome to ThingsBoard RPC debug terminal.\\n\\n'';\n    if (!rpcEnabled) {\n        greetings += ''Target device is not set!\\n\\n'';\n        prompt = '''';\n    } else {\n        greetings += ''Current target device for RPC commands: [[b;#fff;]'' + deviceName + '']\\n\\n'';\n        greetings += ''Please type [[b;#fff;]\\''help\\''] to see usage.\\n'';\n        prompt = ''[[b;#8bc34a;]'' + deviceName +'']> '';\n    }\n    \n    var terminal = $(''#device-terminal'', self.ctx.$container).terminal(\n        function(command) {\n            if (command !== '''') {\n                try {\n                    var localCommand = command.trim();\n                    var requestUUID = uuidv4();\n                    if (localCommand === ''help'') {\n                        printUsage(this);\n                    } else {\n                        var spaceIndex = localCommand.indexOf('' '');\n                        if (spaceIndex === -1 && !localCommand.length) {\n                            this.error(\"Wrong number of arguments!\");\n                            this.echo('' '');\n                        } else {\n                            var params;\n                            if (spaceIndex === -1) {\n                                spaceIndex = localCommand.length;\n                            }\n                            var name = localCommand.substr(0, spaceIndex);\n                            var args = localCommand.substr(spaceIndex + 1);\n                            if (args.length) {\n                                try {\n                                    params = JSON.parse(args);\n                                } catch (e) {\n                                    params = args;\n                                }\n                            }\n                            performRpc(this, name, params, requestUUID);\n                        }\n                    }\n                } catch(e) {\n                    this.error(new String(e));\n                }\n            } else {\n               this.echo('''');\n            }\n        }, {\n            greetings: greetings,\n            prompt: prompt,\n            enabled: rpcEnabled\n    });\n    \n    if (!rpcEnabled) {\n        terminal.error(''No RPC target detected!'').pause();\n    }\n}\n\n\nfunction printUsage(terminal) {\n    var commandsListText = ''\\n[[b;#fff;]Usage:]\\n'';\n    commandsListText += ''   <method> [params body]\\n\\n'';\n    commandsListText += ''[[b;#fff;]Example 1:]\\n''; \n    commandsListText += ''   myRemoteMethod1 myText\\n\\n''; \n    commandsListText += ''[[b;#fff;]Example 2:]\\n''; \n    commandsListText += ''   myOtherRemoteMethod \"{\\\\\"key1\\\\\": 2, \\\\\"key2\\\\\": \\\\\"myVal\\\\\"}\"\\n''; \n    terminal.echo(new String(commandsListText));\n}\n\n\nfunction performRpc(terminal, method, params, requestUUID) {\n    terminal.pause();\n    self.ctx.controlApi.sendTwoWayCommand(method, params, requestTimeout, requestPersistent, persistentPollingInterval, requestUUID).subscribe(\n        function success(responseBody) {\n            terminal.echo(JSON.stringify(responseBody));\n            terminal.echo('' '');\n            terminal.resume();\n        },\n        function fail() {\n            var errorText = self.ctx.defaultSubscription.rpcErrorText;\n            terminal.error(errorText);\n            terminal.echo('' '');\n            terminal.resume();\n        }\n    );\n}\n\n\nfunction uuidv4() {\n  return ''xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx''.replace(/[xy]/g, function(c) {\n    var r = Math.random() * 16 | 0, v = c == ''x'' ? r : (r & 0x3 | 0x8);\n    return v.toString(16);\n  });\n}\n\n  \nself.onDestroy = function() {\n    self.ctx.controlApi.completedCommand();\n}","dataKeySettingsSchema":"{}\n","settingsDirective":"tb-rpc-terminal-widget-settings","defaultConfig":"{\"targetDeviceAliases\":[],\"showTitle\":true,\"backgroundColor\":\"#010101\",\"color\":\"rgba(255, 254, 254, 0.87)\",\"padding\":\"0px\",\"settings\":{\"parseGpioStatusFunction\":\"return body[pin] === true;\",\"gpioStatusChangeRequest\":{\"method\":\"setGpioStatus\",\"paramsBody\":\"{\\n   \\\"pin\\\": \\\"{$pin}\\\",\\n   \\\"enabled\\\": \\\"{$enabled}\\\"\\n}\"},\"requestTimeout\":500,\"switchPanelBackgroundColor\":\"#b71c1c\",\"gpioStatusRequest\":{\"method\":\"getGpioStatus\",\"paramsBody\":\"{}\"},\"gpioList\":[{\"pin\":1,\"label\":\"GPIO 1\",\"row\":0,\"col\":0,\"_uniqueKey\":0},{\"pin\":2,\"label\":\"GPIO 2\",\"row\":0,\"col\":1,\"_uniqueKey\":1},{\"pin\":3,\"label\":\"GPIO 3\",\"row\":1,\"col\":0,\"_uniqueKey\":2}]},\"title\":\"RPC debug terminal\",\"dropShadow\":true,\"enableFullscreen\":true,\"widgetStyle\":{},\"titleStyle\":{\"fontSize\":\"16px\",\"fontWeight\":400},\"showLegend\":false,\"actions\":{}}"}', 'RPC debug terminal', '13814000-1dd2-11b2-8080-808080808080', 'tb-image;/api/images/system/rpc_debug_terminal_system_widget_image.png', 'f', 'f', 'Allows to send any RPC command using its name and parameters to the device. Useful for debugging.', '{command,downlink,"device configuration","device control",invocation,"remote method","remote function",interface,"subroutine call","inter-process communication","server request"}', NULL, 1, 'rpc', '[{"id" : "ede0a0e0-6570-11f1-9578-071530b96ddb", "name" : "Control widgets"}]');
