riable) {\n        return utils.customTranslation(variable, variable);\n        \n    }\n}\n\nself.actionSources = function() {\n    return {\n        ''elementClick'': {\n            name: ''widget-action.element-click'',\n            multiple: true\n        }\n    };\n}\n\nself.onDestroy = function() {\n}\n","settingsDirective":"tb-html-card-widget-settings","defaultConfig":"{\"datasources\":[{\"type\":\"static\",\"name\":\"function\",\"dataKeys\":[{\"name\":\"f(x)\",\"type\":\"function\",\"label\":\"Random\",\"color\":\"#2196f3\",\"settings\":{},\"_hash\":0.15479322438769105,\"funcBody\":\"var value = prevValue + Math.random() * 100 - 50;\\nvar multiplier = Math.pow(10, 2 || 0);\\nvar value = Math.round(value * multiplier) / multiplier;\\nif (value < -1000) {\\n\\tvalue = -1000;\\n} else if (value > 1000) {\\n\\tvalue = 1000;\\n}\\nreturn value;\"}]}],\"showTitle\":false,\"backgroundColor\":\"rgb(255, 255, 255)\",\"color\":\"rgba(0, 0, 0, 0.87)\",\"padding\":\"8px\",\"settings\":{\"cardHtml\":\"<div class=''card''>HTML code here</div>\",\"cardCss\":\".card {\\n    font-weight: bold;\\n    font-size: 32px;\\n    color: #999;\\n    width: 100%;\\n    height: 100%;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n}\"},\"title\":\"HTML Card\",\"dropShadow\":true}"}', 'HTML Card', '13814000-1dd2-11b2-8080-808080808080', 'tb-image;/api/images/system/html_card_system_widget_image.png', 'f', 'f', 'Useful to inject custom HTML code. Designed to display static information only.', '{web,markup}', NULL, 1, 'static', '[{"id" : "edc24370-6570-11f1-9578-071530b96ddb", "name" : "Cards"},{"id" : "ee622cf0-6570-11f1-9578-071530b96ddb", "name" : "HTML widgets"}]');
